/* @autogenerated */
import { normalizeHeader } from './column-match';
import { ImportMessage, ImportPlanColumn } from './entity-import.model';

/** Valor interpretado de una celda (`undefined` si está vacía) o el motivo por el que no se ha podido leer. */
export type CellResult = { value: unknown } | { error: ImportMessage };

const TRUE_WORDS = ['true', 'verdadero', 'si', 's', 'yes', 'y', 'x', '1'];
const FALSE_WORDS = ['false', 'falso', 'no', 'n', '0'];

/** `dd/mm/yyyy` o `dd-mm-yyyy`, con hora `hh:mm[:ss]` opcional. */
const DAY_FIRST = /^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})(?:[ T](\d{1,2}):(\d{2})(?::(\d{2}))?)?$/;
/** `yyyy-mm-dd` sin zona: es una fecha local, no UTC. */
const LOCAL_ISO_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

/**
 * Interpreta una celda según el tipo de la columna. Una celda vacía no aporta valor: al actualizar se conserva
 * el que ya tenía el elemento. Las referencias se devuelven como texto: las resuelve quien importa.
 */
export function parseCell(raw: unknown, column: ImportPlanColumn): CellResult {
  if (raw === null || raw === undefined || (typeof raw === 'string' && raw.trim() === '')) {
    return { value: undefined };
  }
  switch (column.type) {
    case 'number':
      return parseNumber(raw, column);
    case 'boolean':
      return parseBoolean(raw, column);
    case 'date':
    case 'datetime':
      return parseDate(raw, column);
    case 'enum':
      return parseEnum(raw, column);
    default:
      return { value: raw instanceof Date ? raw.toISOString() : String(raw).trim() };
  }
}

function parseNumber(raw: unknown, column: ImportPlanColumn): CellResult {
  if (typeof raw === 'number') {
    return { value: raw };
  }
  const text = String(raw).trim().replace(/\s/g, '');
  // "1.234,5" y "1,234.5": el último separador es el decimal
  const decimal = Math.max(text.lastIndexOf(','), text.lastIndexOf('.'));
  const normalized =
    decimal < 0 ? text : text.substring(0, decimal).replace(/[.,]/g, '') + '.' + text.substring(decimal + 1);
  const value = Number(normalized);
  return isNaN(value) ? invalid('number', raw, column) : { value };
}

function parseBoolean(raw: unknown, column: ImportPlanColumn): CellResult {
  if (typeof raw === 'boolean') {
    return { value: raw };
  }
  const text = normalizeHeader(raw);
  if (TRUE_WORDS.includes(text)) {
    return { value: true };
  }
  if (FALSE_WORDS.includes(text)) {
    return { value: false };
  }
  return invalid('boolean', raw, column);
}

function parseDate(raw: unknown, column: ImportPlanColumn): CellResult {
  let date: Date | null = null;
  if (raw instanceof Date) {
    date = raw;
  } else if (typeof raw === 'string') {
    const text = raw.trim();
    const dayFirst = DAY_FIRST.exec(text);
    const localIso = LOCAL_ISO_DATE.exec(text);
    if (dayFirst) {
      const [, d, m, y, h, min, s] = dayFirst;
      date = new Date(Number(y), Number(m) - 1, Number(d), Number(h ?? 0), Number(min ?? 0), Number(s ?? 0));
    } else if (localIso) {
      date = new Date(Number(localIso[1]), Number(localIso[2]) - 1, Number(localIso[3]));
    } else {
      date = new Date(text);
    }
  }
  if (!date || isNaN(date.getTime())) {
    return invalid('date', raw, column);
  }
  if (column.type === 'date') {
    date = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  }
  return { value: date };
}

function parseEnum(raw: unknown, column: ImportPlanColumn): CellResult {
  const text = normalizeHeader(raw);
  const option = column.options?.find((opt) => opt.names.some((name) => normalizeHeader(name) === text));
  return option ? { value: option.value } : invalid('enum', raw, column);
}

function invalid(kind: string, raw: unknown, column: ImportPlanColumn): CellResult {
  return {
    error: { key: `common.import.error.invalid.${kind}`, params: { field: column.label, value: String(raw) } },
  };
}
